/**
 * Derives the owner's locality, preferring the postcode: the region whose {@link #REGION_POSTCODES}
 * range contains the (4-digit) postcode is returned, and only when the postcode is absent or in no
 * known range does it fall back to the fixed {@link #CITY_REGION} city table. Returns the canonical
 * region string, or {@code "UNKNOWN"} when neither source resolves a region.
 */
default String locality(Owner owner) {
    String fromPostcode = regionForPostcode(owner.getPostcode());
    if (fromPostcode != null) {
        return fromPostcode;
    }
    return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
}

/**
 * Resolves the region whose postcode range contains {@code postcode}, or {@code null} when the
 * postcode is absent, not a 4-digit number, or in no known region range.
 */
default String regionForPostcode(String postcode) {
    if (postcode == null) {
        return null;
    }
    int value;
    try {
        value = Integer.parseInt(postcode.trim());
    }
    catch (NumberFormatException ex) {
        return null;
    }
    for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
        int[] range = entry.getValue();
        if (value >= range[0] && value <= range[1]) {
            return entry.getKey();
        }
    }
    return null;
}

